```python
# 推斷：資料表=上月名冊（表頭第 1 列）, 本月名冊（表頭第 1 列）｜欄位=員工編號，姓名｜主檔=上月名冊｜鍵=員工編號｜篩選=本月名冊中不存在｜輸出=新工作表
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)

ws_last = wb['上月名冊']
ws_this = wb['本月名冊']

def get_header_map(ws, header_row=1):
    """讀取表頭列建立欄名->索引對照，索引為 1-based"""
    header_map = {}
    for col_idx, col in enumerate(ws.iter_cols(min_row=header_row, max_row=header_row, values_only=True), start=1):
        cell_val = col[0]
        if cell_val is not None:
            header_map[str(cell_val).strip()] = col_idx
    return header_map

def normalize_id(val):
    """正規化員工編號：去除空白、轉大寫，以便比對"""
    if val is None:
        return ""
    return str(val).strip().upper()

# 取得兩張表的欄位對照
map_last = get_header_map(ws_last, 1)
map_this = get_header_map(ws_this, 1)

id_col_last = map_last.get('員工編號')
name_col_last = map_last.get('姓名')
id_col_this = map_this.get('員工編號')

if not all([id_col_last, name_col_last, id_col_this]):
    raise ValueError("缺少必要欄位：員工編號 或 姓名")

# 收集本月名冊的員工編號集合 (正規化後)
this_month_ids = set()
for row in ws_this.iter_rows(min_row=2, values_only=True):
    if len(row) >= id_col_this:
        val = row[id_col_this - 1]
        if val:
            this_month_ids.add(normalize_id(val))

# 篩選上月名冊中不在本月名冊的資料
result_rows = []
for row in ws_last.iter_rows(min_row=2, values_only=True):
    if len(row) >= id_col_last:
        val_id = row[id_col_last - 1]
        if val_id:
            norm_id = normalize_id(val_id)
            # 若正規化後的 ID 不在本月名冊中，則保留
            if norm_id not in this_month_ids:
                val_name = row[name_col_last - 1] if len(row) >= name_col_last else ""
                result_rows.append((val_id, val_name))

# 建立新工作表
new_ws = wb.create_sheet(title="上月有本月無名單")
new_ws.append(['員工編號', '姓名'])
for r in result_rows:
    new_ws.append(r)

wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=上期報價，本期報價（表頭第 1 列）｜欄位=品號，品名｜主檔=上期報價｜鍵=品號｜篩選=本期報價中不存在｜輸出=新工作表
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)

# 輔助函數：根據表頭名稱取得欄位索引 (1-based)
def get_header_map(sheet, header_row=1):
    mapping = {}
    for col in range(1, sheet.max_column + 1):
        val = sheet.cell(row=header_row, column=col).value
        if val:
            mapping[str(val).strip()] = col
    return mapping

# 輔助函數：正規化品號 (去除空白、轉大寫) 以進行準確比對
def normalize_id(val):
    if val is None:
        return ""
    return str(val).strip().upper()

# 讀取上期報價 (主檔)
sheet_prev = wb['上期報價']
map_prev = get_header_map(sheet_prev)
col_id_prev = map_prev.get('品號')
col_name_prev = map_prev.get('品名')

prev_items = []
if col_id_prev and col_name_prev:
    for row in range(2, sheet_prev.max_row + 1):
        raw_id = sheet_prev.cell(row=row, column=col_id_prev).value
        name = sheet_prev.cell(row=row, column=col_name_prev).value
        if raw_id is not None:
            prev_items.append({
                'raw_id': raw_id,
                'name': name,
                'norm_id': normalize_id(raw_id)
            })

# 讀取本期報價 (比對檔)
sheet_curr = wb['本期報價']
map_curr = get_header_map(sheet_curr)
col_id_curr = map_curr.get('品號')

curr_ids_set = set()
if col_id_curr:
    for row in range(2, sheet_curr.max_row + 1):
        val = sheet_curr.cell(row=row, column=col_id_curr).value
        if val is not None:
            curr_ids_set.add(normalize_id(val))

# 找出缺項 (在上期但不在本期)
missing_items = []
for item in prev_items:
    if item['norm_id'] not in curr_ids_set:
        missing_items.append(item)

# 建立新工作表
new_sheet = wb.create_sheet('本期缺項')
new_sheet.append(['品號', '品名'])

for item in missing_items:
    new_sheet.append([item['raw_id'], item['name']])

wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=系統帳，實盤（表頭第 1 列）｜欄位=料號，品名｜主檔=系統帳｜鍵=料號｜篩選=系統帳有但實盤無｜輸出=新工作表 (刪除明細)
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)

sheet_system = wb['系統帳']
sheet_physical = wb['實盤']

def get_col_index(sheet, header_name):
    """根據表頭名稱返回欄位索引 (1-based)"""
    for row in sheet.iter_rows(min_row=1, max_row=1, values_only=True):
        for idx, cell_value in enumerate(row, start=1):
            if cell_value is not None and str(cell_value).strip() == header_name:
                return idx
    return None

def normalize_key(val):
    """標準化料號：去除前後空白、轉大寫"""
    if val is None:
        return ""
    return str(val).strip().upper()

# 獲取欄位索引
sys_item_idx = get_col_index(sheet_system, '料號')
sys_name_idx = get_col_index(sheet_system, '品名')
phy_item_idx = get_col_index(sheet_physical, '料號')

# 建立實盤料號集合 (用於快速查找)
physical_keys = set()
if phy_item_idx:
    for row in sheet_physical.iter_rows(min_row=2, values_only=True):
        if len(row) >= phy_item_idx:
            val = row[phy_item_idx - 1]
            if val is not None:
                physical_keys.add(normalize_key(val))

# 找出系統帳中有但實盤中無的資料 (被刪掉的)
deleted_items = []
if sys_item_idx and sys_name_idx:
    for row in sheet_system.iter_rows(min_row=2, values_only=True):
        if len(row) >= sys_item_idx:
            val = row[sys_item_idx - 1]
            if val is not None and normalize_key(val) not in physical_keys:
                name = row[sys_name_idx - 1] if len(row) >= sys_name_idx else ""
                deleted_items.append((val, name))

# 建立新工作表
new_ws = wb.create_sheet('刪除明細')
new_ws.append(['料號', '品名'])
for item in deleted_items:
    new_ws.append(item)

wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=上期報價，本期報價（表頭第 1 列）｜欄位=品號，品名｜主檔=上期報價｜鍵=品號｜篩選=本期無｜輸出=新工作表
from openpyxl import load_workbook

wb = load_workbook(INPUT_PATH)

# 輔助函數：取得欄位名稱對應的索引 (0-based)
def get_header_map(sheet, header_row=1):
    mapping = {}
    # 讀取表頭列的所有儲存格
    for col_idx, cell in enumerate(sheet[header_row]):
        if cell.value is not None:
            key = str(cell.value).strip()
            if key not in mapping:
                mapping[key] = col_idx
    return mapping

# 輔助函數：正規化品號 (去除空白、轉大寫)
def normalize_item_no(val):
    if val is None:
        return ""
    return str(val).strip().upper()

# 1. 讀取本期報價，建立品號集合 (用於比對)
sheet_current = wb["本期報價"]
header_current = get_header_map(sheet_current)
item_no_idx_current = header_current.get("品號")
current_item_set = set()

if item_no_idx_current is not None:
    # 資料從第 2 列開始
    for row in sheet_current.iter_rows(min_row=2, values_only=True):
        if len(row) > item_no_idx_current:
            val = row[item_no_idx_current]
            if val is not None:
                norm_val = normalize_item_no(val)
                if norm_val:
                    current_item_set.add(norm_val)

# 2. 讀取上期報價，篩選出本期沒有的
sheet_prev = wb["上期報價"]
header_prev = get_header_map(sheet_prev)
item_no_idx_prev = header_prev.get("品號")
item_name_idx_prev = header_prev.get("品名")

diff_data = []

if item_no_idx_prev is not None and item_name_idx_prev is not None:
    for row in sheet_prev.iter_rows(min_row=2, values_only=True):
        # 確保列長度足夠
        if len(row) > max(item_no_idx_prev, item_name_idx_prev):
            raw_item_no = row[item_no_idx_prev]
            if raw_item_no is not None:
                norm_val = normalize_item_no(raw_item_no)
                # 如果正規化後的品號不在本期集合中，則保留
                if norm_val and norm_val not in current_item_set:
                    # 保留原始資料 (品號、品名)
                    diff_data.append([raw_item_no, row[item_name_idx_prev]])

# 3. 建立新工作表
new_sheet_name = "上期独有品項"
if new_sheet_name in wb.sheetnames:
    wb.remove(wb[new_sheet_name])
new_sheet = wb.create_sheet(title=new_sheet_name)

# 寫入表頭
new_sheet.append(["品號", "品名"])

# 寫入資料
for row_data in diff_data:
    new_sheet.append(row_data)

wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=上月名冊/本月名冊（表頭第 1 列）｜欄位=員工編號、姓名、時數、部門、職稱｜主檔=兩表比對｜鍵=員工編號｜篩選=欄位值不同｜輸出=新工作表

from openpyxl import Workbook, load_workbook

# 讀取工作簿
wb = load_workbook(INPUT_PATH)

# 讀取兩個工作表
last_month_ws = wb['上月名冊']
this_month_ws = wb['本月名冊']

# 取得表頭欄位（第 1 列）
last_month_headers = [last_month_ws.cell(row=1, column=c).value for c in range(1, last_month_ws.max_column + 1)]
this_month_headers = [this_month_ws.cell(row=1, column=c).value for c in range(1, this_month_ws.max_column + 1)]

# 建立欄名→索引對照（排除員工編號作為鍵）
last_month_col_map = {h: i for i, h in enumerate(last_month_headers, start=1)}
this_month_col_map = {h: i for i, h in enumerate(this_month_headers, start=1)}

# 讀取資料（從第 2 列開始），以員工編號為鍵建立字典
last_month_data = {}
this_month_data = {}

for row in range(2, last_month_ws.max_row + 1):
    emp_id = last_month_ws.cell(row=row, column=last_month_col_map['員工編號']).value
    if emp_id:
        last_month_data[emp_id] = {h: last_month_ws.cell(row=row, column=last_month_col_map[h]).value for h in last_month_headers}

for row in range(2, this_month_ws.max_row + 1):
    emp_id = this_month_ws.cell(row=row, column=this_month_col_map['員工編號']).value
    if emp_id:
        this_month_data[emp_id] = {h: this_month_ws.cell(row=row, column=this_month_col_map[h]).value for h in this_month_headers}

# 建立新工作表
new_ws = wb.create_sheet(title='欄位變更比對')

# 寫入新表表頭
new_headers = ['員工編號', '變更欄位', '舊值', '新值']
for col, h in enumerate(new_headers, start=1):
    new_ws.cell(row=1, column=col, value=h)

# 比對變更，照原表順序（以上月名冊順序為準）
output_row = 2
for emp_id in last_month_data.keys():
    if emp_id in this_month_data:
        # 逐欄比對（照原表欄位順序，排除員工編號）
        for header in last_month_headers:
            if header == '員工編號':
                continue
            old_val = last_month_data[emp_id].get(header)
            new_val = this_month_data[emp_id].get(header)
            if old_val != new_val:
                new_ws.cell(row=output_row, column=1, value=emp_id)
                new_ws.cell(row=output_row, column=2, value=header)
                new_ws.cell(row=output_row, column=3, value=old_val)
                new_ws.cell(row=output_row, column=4, value=new_val)
                output_row += 1

# 儲存工作簿
wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=上期報價、本期報價（表頭第 1 列）｜欄位=品號、品名、單價、幣別、計價單位｜主檔=上期報價｜鍵=品號（A 欄）｜篩選=欄位值變更｜輸出=新工作表「變更記錄」

from openpyxl import load_workbook

# 讀取工作簿
wb = load_workbook(INPUT_PATH)

# 讀取兩個工作表
ws_prev = wb['上期報價']
ws_curr = wb['本期報價']

# 建立欄名→索引對照（表頭在第 1 列）
prev_headers = {cell.value: idx for idx, cell in enumerate(ws_prev[1], start=1)}
curr_headers = {cell.value: idx for idx, cell in enumerate(ws_curr[1], start=1)}

# 欄位順序（排除鍵「品號」）
key_col = 1  # 品號在 A 欄
compare_cols = [2, 3, 4, 5]  # 品名、單價、幣別、計價單位
col_names = {2: '品名', 3: '單價', 4: '幣別', 5: '計價單位'}

# 讀取上期報價資料（品號→整列資料）
prev_data = {}
prev_row_order = []  # 保持原順序
for row in range(2, ws_prev.max_row + 1):
    key = ws_prev.cell(row=row, column=key_col).value
    if key:
        prev_data[key] = {col: ws_prev.cell(row=row, column=col).value for col in compare_cols}
        prev_row_order.append((row, key))

# 讀取本期報價資料（品號→整列資料）
curr_data = {}
for row in range(2, ws_curr.max_row + 1):
    key = ws_curr.cell(row=row, column=key_col).value
    if key:
        curr_data[key] = {col: ws_curr.cell(row=row, column=col).value for col in compare_cols}

# 比對並收集變更
changes = []
for row_num, key in prev_row_order:
    if key in curr_data:
        for col in compare_cols:
            old_val = prev_data[key][col]
            new_val = curr_data[key][col]
            if old_val != new_val:
                changes.append({
                    '品號': key,
                    '變更欄位': col_names[col],
                    '舊值': old_val,
                    '新值': new_val
                })

# 建立新工作表
if '變更記錄' in wb.sheetnames:
    del wb['變更記錄']
ws_new = wb.create_sheet('變更記錄')

# 寫入表頭
headers = ['品號', '變更欄位', '舊值', '新值']
for col, h in enumerate(headers, start=1):
    ws_new.cell(row=1, column=col, value=h)

# 寫入資料
for row_idx, change in enumerate(changes, start=2):
    ws_new.cell(row=row_idx, column=1, value=change['品號'])
    ws_new.cell(row=row_idx, column=2, value=change['變更欄位'])
    ws_new.cell(row=row_idx, column=3, value=change['舊值'])
    ws_new.cell(row=row_idx, column=4, value=change['新值'])

# 儲存
wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=系統帳/實盤（表頭第 1 列）｜欄位=料號/品名/數量/儲位/單位｜主檔=系統帳｜鍵=料號(A 欄)｜篩選=兩表同料號其他欄位值不同｜輸出=新工作表「變更明細」

from openpyxl import load_workbook

# 讀取工作簿
wb = load_workbook(INPUT_PATH)

# 讀取系統帳和實盤資料
ws_system = wb['系統帳']
ws_actual = wb['實盤']

# 建立欄名→索引對照（表頭在第 1 列）
system_headers = {}
actual_headers = {}
for col in range(1, ws_system.max_column + 1):
    system_headers[ws_system.cell(1, col).value] = col
for col in range(1, ws_actual.max_column + 1):
    actual_headers[ws_actual.cell(1, col).value] = col

# 建立實盤的料號→資料對照
actual_data = {}
for row in range(2, ws_actual.max_row + 1):
    item_no = ws_actual.cell(row, actual_headers['料號']).value
    if item_no:
        actual_data[item_no] = {}
        for header, col_idx in actual_headers.items():
            if header != '料號':
                actual_data[item_no][header] = ws_actual.cell(row, col_idx).value

# 收集變更記錄（依系統帳原列序）
changes = []
for row in range(2, ws_system.max_row + 1):
    item_no = ws_system.cell(row, system_headers['料號']).value
    if item_no and item_no in actual_data:
        # 依原表欄位順序檢查每個欄位（排除料號）
        for col in range(1, ws_system.max_column + 1):
            header = ws_system.cell(1, col).value
            if header == '料號':
                continue
            old_val = ws_system.cell(row, col).value
            new_val = actual_data[item_no].get(header, '')
            if old_val != new_val:
                changes.append([item_no, header, old_val, new_val])

# 建立新工作表
ws_new = wb.create_sheet('變更明細')
ws_new.append(['料號', '變更欄位', '舊值', '新值'])
for change in changes:
    ws_new.append(change)

# 儲存
wb.save(OUTPUT_PATH)
```
